INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Freeware dasselbe wie Open-Source-Software?', 2, '[{"text": "No", "correct": true, "because": "Kostenlos vs. Quellcode offen"}, {"text": "Yes", "correct": false, "because": "Different concepts"}]'),
('00000000-0000-0000-0000-000000000000', 'What is the primary purpose of freeware?', 3, '[{"text": "Provide software at no cost", "correct": true, "because": "Free access"}, {"text": "Encrypt data", "correct": false, "because": "Not primary"}, {"text": "Enhance hardware", "correct": false, "because": "Software focus"}]'),
('00000000-0000-0000-0000-000000000000', 'Which examples are considered freeware?', 5, '[{"text": "VLC Media Player", "correct": true, "because": "Free software"}, {"text": "GIMP", "correct": true, "because": "Free graphics tool"}, {"text": "Microsoft Office", "correct": false, "because": "Paid software"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) Freeware is available without charge. b) It always includes source code.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Source code optional"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I ignore with freeware?', 4, '[{"text": "License terms", "correct": false, "because": "Usage conditions"}, {"text": "Distribution rights", "correct": false, "because": "Often restricted"}, {"text": "Paper size", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if freeware can have usage restrictions?', 2, '[{"text": "Yes", "correct": true, "because": "E.g., non-commercial use"}, {"text": "No", "correct": false, "because": "Restrictions possible"}]'),
('00000000-0000-0000-0000-000000000000', 'Which software type is often freeware?', 3, '[{"text": "Utilities", "correct": true, "because": "E.g., CCleaner"}, {"text": "Operating systems", "correct": false, "because": "Rarely free"}, {"text": "Printer drivers", "correct": false, "because": "Hardware-specific"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does freeware offer?', 5, '[{"text": "Cost savings", "correct": true, "because": "No purchase needed"}, {"text": "Wide availability", "correct": true, "because": "Freely distributed"}, {"text": "High-speed hardware", "correct": false, "because": "Not hardware-related"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard: a) Freeware is free to use. b) It’s always open-source. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Not always open"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need for freeware?', 4, '[{"text": "License agreement", "correct": false, "because": "Defines terms"}, {"text": "Installation", "correct": false, "because": "Software use"}, {"text": "Payment", "correct": true, "because": "Free by definition"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Is freeware always ad-free?', 2, '[{"text": "No", "correct": true, "because": "May include ads"}, {"text": "Yes", "correct": false, "because": "Ads possible"}]'),
('00000000-0000-0000-0000-000000000000', 'Which tools might be freeware?', 4, '[{"text": "PDF readers", "correct": true, "because": "E.g., Adobe Reader"}, {"text": "Antivirus software", "correct": true, "because": "E.g., Avast Free"}, {"text": "Paper cutters", "correct": false, "because": "Not software"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard that freeware has no support. Is that true?', 2, '[{"text": "No", "correct": true, "because": "Support varies"}, {"text": "Yes", "correct": false, "because": "Sometimes offered"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I prioritize with freeware?', 3, '[{"text": "License terms", "correct": true, "because": "Usage rules"}, {"text": "Paper type", "correct": false, "because": "Irrelevant"}, {"text": "Speed", "correct": false, "because": "Functionality first"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) Freeware can be proprietary. b) It’s always editable.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Not always open"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What risks come with freeware?', 5, '[{"text": "Malware", "correct": true, "because": "Potential security issue"}, {"text": "Limited support", "correct": true, "because": "No guaranteed help"}, {"text": "High cost", "correct": false, "because": "Free by definition"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s unimportant for freeware?', 3, '[{"text": "Usage restrictions", "correct": false, "because": "License key"}, {"text": "Software functionality", "correct": false, "because": "Core aspect"}, {"text": "Font style", "correct": true, "because": "No impact"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Can freeware be used commercially?', 3, '[{"text": "Yes", "correct": true, "because": "Depends on license"}, {"text": "No", "correct": false, "because": "Not always restricted"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if freeware requires registration?', 2, '[{"text": "No", "correct": true, "because": "Often optional"}, {"text": "Yes", "correct": false, "because": "Not mandatory"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s central to freeware?', 4, '[{"text": "No cost", "correct": true, "because": "Core principle"}, {"text": "Physical delivery", "correct": false, "because": "Digital"}, {"text": "Paper records", "correct": false, "because": "Irrelevant"}]');
